style.css:
@-moz-document domain("roblox.com") {
body {
    background-color: #121212 !important;
    color: #f0f0f0 !important;
    font-family: 'Segoe UI', sans-serif !important;
  }

  /* Links e botões com toque vermelho (boné) */
  a, button {
    color: #ff3c3c !important;
  }

  a:hover, button:hover {
    background-color: #ff3c3c !important;
    color: #ffffff !important;
    transition: 0.2s ease-in-out;
  }

  /* Cabeçalho e menu escuros */
  header, nav, .navbar, .menu, .header, .top-nav {
    background-color: #1a1a1a !important;
    border-bottom: 2px solid #ff3c3c !important;
  }

  /* Campos de entrada */
  input, textarea, select {
    background-color: #2c2c2c !important;
    color: #ffffff !important;
    border: 1px solid #ff3c3c !important;
  }

  /* Títulos em destaque */
  h1, h2, h3 {
    color: #ff3c3c !important;
    text-transform: uppercase;
    letter-spacing: 1px;
  }

  /* Imagens com leve sombra */
  img {
    border-radius: 8px !important;
    box-shadow: 0 0 10px #00000077;
  }

  ::selection {
    background: #ff3c3c !important;
    color: #ffffff !important;
  }

  /* Detalhes adicionais visuais */
  .btn-primary {
    background-color: #ff3c3c !important;
    border: none !important;
    color: #fff !important;
  }

  .btn-primary:hover {
    background-color: #e60000 !important;
  }
}
